import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Follow along: export result notifications and read state","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/export-notifications"},"headers":[],"relativePath":"en/tutorials/export-notifications.md","filePath":"en/tutorials/export-notifications.md"}'),o={name:"en/tutorials/export-notifications.md"};function n(r,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="follow-along-export-result-notifications-and-read-state" tabindex="-1">Follow along: export result notifications and read state <a class="header-anchor" href="#follow-along-export-result-notifications-and-read-state" aria-label="Permalink to &quot;Follow along: export result notifications and read state&quot;">​</a></h1><p>Continuing from <a href="./document-exports">document exports</a>: run <code>just dev</code>, sign in, save a Markdown document and request an export. Once the Worker finishes, open &quot;Notifications&quot; from the home page and see &quot;Document export completed&quot; plus the unread count. Clicking &quot;View result&quot; marks the notification read and opens that export&#39;s details, where the ZIP can be downloaded; going back to the notifications and refreshing, the read state persists.</p><p>If the job fails for good, you see &quot;Document export failed&quot;. A transient failure entering its retry wait raises no notification; only after <a href="./job-recovery">job recovery</a> exhausts the budget or hits a permanent error does one arrive. The details query the current result, so if an administrator later recovers the task, the original failure notice still leads you to the latest successful state.</p><h2 id="_1-register-the-intent-first-publish-the-result-later" tabindex="-1">1. Register the intent first, publish the result later <a class="header-anchor" href="#_1-register-the-intent-first-publish-the-result-later" aria-label="Permalink to &quot;1. Register the intent first, publish the result later&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/crates/app/src/modules/knowledge/exports/requests.rs" target="_blank" rel="noreferrer">export request</a> saves the snapshot, enqueues the job, calls Core <code>notifications::on_job_outcome</code>, then writes the audit entry and the idempotent response — all in the same PostgreSQL transaction. The registration records:</p><ul><li>the recipient: the user who requested the export;</li><li>the event key: <code>knowledge.export:&lt;export_id&gt;</code>;</li><li>a generic description: &quot;文档导出&quot; (document export). Private document titles, bodies or signed links are never copied here;</li><li>the navigation target: type <code>knowledge.export</code>, the export ID, and the document ID in the context.</li></ul><p>The intent is stored in Core&#39;s <code>job_notifications</code> and does not appear in the notification list yet. When the transaction rolls back, the job, snapshot, intent and audit entry are withdrawn together. Core does not read knowledge tables; even if the documents and export records are cleaned up later, the intent still allows the final failure notification to reach the original requester.</p><h2 id="_2-the-result-and-the-notification-commit-together" tabindex="-1">2. The result and the notification commit together <a class="header-anchor" href="#_2-the-result-and-the-notification-commit-together" aria-label="Permalink to &quot;2. The result and the notification commit together&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Core Jobs</a> calls Notifications at three terminal points: a success committed under a valid lease, a failure reaching its terminal state, and a claim discovering that the previous execution crashed with its budget exhausted.</p><p>When a ZIP is published successfully, the file state, the export result, the audit entry, the job&#39;s terminal state and the in-app notification share one database transaction. If the notification insert fails, none of the other database outcomes may turn successful on their own; objects already uploaded but unadopted remain managed by the <a href="./deletion-cleanup">cleanup mechanism</a>. Failure notifications commit together with the job/history state too, and never depend on a handler staying alive long enough to reach an error branch.</p><p>Jobs that registered no notification intent produce no notifications — background file cleanup, for example. In-app notifications here are only a database operation; the later mail chapter is where external delivery appears.</p><h2 id="_3-why-retries-do-not-re-notify" tabindex="-1">3. Why retries do not re-notify <a class="header-anchor" href="#_3-why-retries-do-not-re-notify" aria-label="Permalink to &quot;3. Why retries do not re-notify&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/migrations/0013_notifications.sql" target="_blank" rel="noreferrer">notifications migration</a> keeps logical messages unique with <code>(recipient_id, event_key, outcome)</code>. Repeated executions meeting the same success or failure event keep the original message, including its ID, creation time and read time.</p><p>One export that fails first and succeeds after an explicit administrator retry can hold one failure notification and one success notification. Repeated failures do not pile up alerts, and repeated successes do not turn unread again. A new export request owns a new export ID and therefore produces an independent event.</p><h2 id="_4-the-inbox-belongs-to-the-current-user-only" tabindex="-1">4. The inbox belongs to the current user only <a class="header-anchor" href="#_4-the-inbox-belongs-to-the-current-user-only" aria-label="Permalink to &quot;4. The inbox belongs to the current user only&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/crates/app/src/modules/notifications/inbox.rs" target="_blank" rel="noreferrer">Core inbox</a> provides the two interfaces from the generated contract:</p><ul><li><code>GET /api/v1/notifications</code>: read newest first; 50 per page by default, 100 at most, with <code>unread_only=true</code> and the returned cursor to continue. The cursor binds to the current user and filter, and the unread total with that page share one database snapshot.</li><li><code>POST /api/v1/notifications/{id}/read</code>: requires the current session, Origin and CSRF; repeated calls keep the first <code>read_at</code>.</li></ul><p>Queries and updates both address the current user as the recipient; even an administrator cannot read or modify someone else&#39;s inbox. Responses contain no job payloads, credentials or download capabilities. Reading a notification never grants access to its target resource.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/packages/views/src/notifications/notifications-view.tsx" target="_blank" rel="noreferrer">shared NotificationsView</a> calls the generated SDK and renders loading, empty lists, unread counts, failures, retries and paging; the page text, error messages and dates all come from the Core bilingual catalog and follow the interface language (UI09). Clicking &quot;Refresh notifications&quot; returns to the newest page; page state and the Query cache are isolated per identity.</p><h2 id="_5-display-and-target-resolution-belong-to-the-example" tabindex="-1">5. Display and target resolution belong to the example <a class="header-anchor" href="#_5-display-and-target-resolution-belong-to-the-example" aria-label="Permalink to &quot;5. Display and target resolution belong to the example&quot;">​</a></h2><p>Both the display and the navigation target are owned by the knowledge example; Core only consumes the registered interface from the assembly point (docs/ui/design.md §4.1). The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/packages/views/src/knowledge/app-example.tsx" target="_blank" rel="noreferrer">example contribution</a> registers two things:</p><ul><li><code>describeNotification</code> derives a title key at render time from the structured data (target type <code>knowledge.export</code> plus the outcome); the Core inbox localizes history records into &quot;Document export completed/failed&quot; accordingly — without matching the stored Chinese subject and without rewriting history. Switch the interface to English and the same existing notice immediately shows an English title.</li><li><code>resolveNotificationTarget</code> recognizes <code>knowledge.export</code>, checks the document/export IDs and hands the navigation callback to the Core view; clicking &quot;View result&quot; still goes through real authorization.</li></ul><p>Unregistered or removed types keep the generic display — the original subject plus the outcome word — with only mark-as-read and the &quot;the feature behind this notification is currently unavailable&quot; feedback, never a jump to a page that does not exist; unknown extension subjects render as-is, safely.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/packages/views/src/knowledge/export-detail-view.tsx" target="_blank" rel="noreferrer">export details view</a> re-requests that export, and the backend checks the current session, result ownership and source-document read permission. After the source document is deleted or access revoked, the generic notification can still be read, but the result and new download links are out of reach. Expired results cannot be downloaded; already-issued links keep the TTL boundaries agreed in the attachments and exports chapters.</p><p>This is why removing the knowledge example from the template keeps the notification list, the read-state capability and the generic fallback display. The example manifest registers the export details view, the target-resolution and display mapping, the business tests and this chapter; the Core notifications migration, API, view and general HTTP tests remain.</p><h2 id="_6-verification" tabindex="-1">6. Verification <a class="header-anchor" href="#_6-verification" aria-label="Permalink to &quot;6. Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notifications</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/notifications.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/export-notifications.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The HTTP/public-job tests verify recipient isolation, administrators cannot overreach, CSRF, persistent read state, cursor limits, failure budgets, invalidated leases, retry deduplication and the atomic rollback of notification faults with results. The real-RustFS export tests cover success/failure notifications, denial after the source resources are deleted, and publishing exactly one result after recovery.</p><p>The View tests reuse the existing interfaces: operating the request, states, mark-as-read and opening the target. <code>export-notifications.test.tsx</code> switches the same existing notice to English and verifies the structured display follows the interface language; the unknown-type case verifies the generic fallback and safe display. The design-system showroom demos the export states and the notification display contract in isolation on demo data.</p><p>After the whole key journey passes, run once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/exports.spec.ts</span></span></code></pre></div><p>The real browser registers, writes, uploads an attachment, exports and verifies the ZIP bytes, then opens the real notifications, enters the details and refreshes to confirm the read state. Regular development keeps using the faster interface and View tests.</p><h2 id="_7-swap-in-your-own-business" tabindex="-1">7. Swap in your own business <a class="header-anchor" href="#_7-swap-in-your-own-business" aria-label="Permalink to &quot;7. Swap in your own business&quot;">​</a></h2><p>In your business request transaction, call <code>jobs::enqueue</code> first, then register a stable business event key and recipient with <code>notifications::on_job_outcome</code>. Use a generic description and carry only business identifiers in the target; never copy anything that must not be displayed forever into the inbox.</p><p>In the Worker, keep the existing lease locking and the <code>Lease::succeed</code> transaction boundary; Core publishes the result notifications automatically, including terminal failures and crash-exhausted budgets. Finally, register your own <code>describeNotification</code> display mapping and <code>resolveNotificationTarget</code> resolution callback, the details page and its authorization API in the example contribution, and record the replaceable resources in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">ownership manifest</a>. Notifications never needs to learn about your business tables.</p><hr><p>Source version：<code>4f971ed1cc0b</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/docs/tutorials/13-export-notifications.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,37)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
